// Generated by src/kid_pc_monitor/secrets_store.py (cryptography 48.0.0):
//
//	key = secrets_store._derive_key()
//	Fernet(key)._encrypt_from_parts(plaintext.encode(), 1777000000, iv)
const (
	defaultKey   = "qUqA0U6WzA-GgRiReFTkIGQJvDcJGqpYhxFpUg4w_sI="
	defaultToken = "gAAAAABp6t5AAAECAwQFBgcICQoLDA0OD_OFRh0TKmlE6CdoPCuWAwWGZ0ejHt5aU4hnXhhPx_X-d52027H8ltcRJYONXFCy9DxO4VCHyxyxDkVBrFgcstM="
	defaultPlain = "correct horse battery staple"
	// KID_PC_MONITOR_SECRET_KEY=custom-key
	customKey   = "JnuqeD8ZUjTbWsMmeT6HORRce3jln_IKtxdh07EirG8="
	customToken = "gAAAAABp6t5AEBESExQVFhcYGRobHB0eH6TPfIfmaO-s2UhQhgkkj0rWUkIWlkZQ7qCmYYsPl8Oaxa77F8349WvHVaijn7WyI2_3okj9snIMTlMzcALnm_Y="
	customPlain = "ünïcode secret"
)

func TestKeyDerivationMatchesPython(t *testing.T) {
	t.Setenv(keyEnv, "")
	if got := base64.URLEncoding.EncodeToString(fernetKey()); got != defaultKey {
		t.Errorf("bootstrap key = %s, want %s", got, defaultKey)
	}
	t.Setenv(keyEnv, "  custom-key\n")
	if got := base64.URLEncoding.EncodeToString(fernetKey()); got != customKey {
		t.Errorf("custom key = %s, want %s", got, customKey)
	}
}

func TestDecryptPythonTokens(t *testing.T) {
	for _, tc := range []struct{ key, token, plain string }{
		{defaultKey, defaultToken, defaultPlain},
		{customKey, customToken, customPlain},
		{defaultKey, defaultToken + "\n", defaultPlain},
	} {
		key, _ := base64.URLEncoding.DecodeString(tc.key)
		got, err := fernetDecrypt(key, []byte(tc.token))
		if err != nil || string(got) != tc.plain {
			t.Errorf("decrypt = %q, %v; want %q", got, err, tc.plain)
		}
	}
}

func TestDecryptRejectsBadTokens(t *testing.T) {
	key, _ := base64.URLEncoding.DecodeString(defaultKey)
	wrong, _ := base64.URLEncoding.DecodeString(customKey)
	if _, err := fernetDecrypt(wrong, []byte(defaultToken)); err == nil {
		t.Error("wrong key accepted")
	}
	raw, _ := base64.URLEncoding.DecodeString(defaultToken)
	raw[30] ^= 1
	if _, err := fernetDecrypt(key, []byte(base64.URLEncoding.EncodeToString(raw))); err == nil {
		t.Error("tampered ciphertext accepted")
	}
	for _, bad := range []string{"", "not base64!", "gAAAAA==", defaultToken[:40]} {
		if _, err := fernetDecrypt(key, []byte(bad)); err == nil {
			t.Errorf("%q accepted", bad)
		}
	}
}

func TestLoadSearchesDirsInOrder(t *testing.T) {
	t.Setenv(keyEnv, "")
	dir := t.TempDir()
	t.Setenv(dirEnv, dir)
	if got := Dirs(); len(got) != 1 || got[0] != dir {
		t.Fatalf("override not authoritative: %v", got)
	}
	if _, err := LoadSharedSecret(); !errors.Is(err, ErrNotFound) {
		t.Fatalf("empty dir: %v", err)
	}
	path := filepath.Join(dir, SharedSecretName+".enc")
	if err := os.WriteFile(path, []byte(customToken), 0o600); err != nil {
		t.Fatal(err)
	}
	if _, err := LoadSharedSecret(); !errors.Is(err, ErrNotFound) {
		t.Fatalf("undecryptable file: %v", err)
	}
	if err := os.WriteFile(path, []byte(defaultToken), 0o600); err != nil {
		t.Fatal(err)
	}
	got, err := LoadSharedSecret()
	if err != nil || got != defaultPlain {
		t.Fatalf("got %q, %v", got, err)
	}
}

func TestDefaultDirs(t *testing.T) {
	t.Setenv(dirEnv, "")
	dirs := Dirs()
	if len(dirs) != 2 {
		t.Fatalf("dirs = %v", dirs)
	}
	if filepath.Base(dirs[0]) != dirName || filepath.Base(dirs[1]) != dirName {
		t.Errorf("dirs = %v", dirs)
	}
}

// Multi-block output (64 bytes > one SHA-256 block), checked against
// hashlib.pbkdf2_hmac("sha256", b"passwd", b"salt", 1, 64).
func TestPBKDF2(t *testing.T) {
	got := pbkdf2SHA256([]byte("passwd"), []byte("salt"), 1, 64)
	want := "VawEblbjCJ_sFpHCJUS2BflBhSFt3gRl5oudV8INrLxJypzM8Xm2RZkWZLOdd-8xfHG4RbHjC9UJESBB06GXgw=="
	if base64.URLEncoding.EncodeToString(got) != want {
		t.Fatalf("got %s", base64.URLEncoding.EncodeToString(got))
	}
}
